(194, 2705, 0, 5, 'Samanta Oliveira  Dionel', 'art@gmail.com', 'Gostei passei um pouco no rosto . Acho q vai dar certo ...', 'S', '172.71.6.71', '2022-09-22 16:54:13', '2022-09-22 16:54:13'),
(195, 2705, 0, 5, 'Camila Santo ', 'ert@gmail.com', 'Apaixonada nessa base!! Com pouco produto consigo uma ótima cobertura, e a sensação dela na pele é agradável. Não realçou minhas linhas de expressão, como alguma bases fazem.', 'S', '172.68.54.241', '2022-09-22 16:56:16', '2022-09-22 16:56:16'),
(196, 2704, 0, 5, 'Alessandra', 'ae@gmail.com', 'Chegou certinho, bem embalado, super recomendo', 'S', '172.68.55.14', '2022-09-22 16:57:34', '2022-09-22 16:57:34'),
(197, 2704, 0, 5, 'Sabrina Tamires', 'aert@gmail.com', 'Chegou rapidinho, ainda vou testar', 'S', '172.68.55.14', '2022-09-22 16:58:12', '2022-09-22 16:58:12'),
(198, 2704, 0, 5, 'Erika Almeida ', 'aeq@gmail.com', 'Ameeei achei tudo ! Eu fiquei apaixonada', 'S', '172.68.54.119', '2022-09-22 17:00:28', '2022-09-22 17:00:28'),
(199, 2704, 0, 5, 'Samanta ', 'aqwe@gmail.com', 'Chegou rápido e bem embalado. Recomendo!', 'S', '172.68.54.119', '2022-09-22 17:14:23', '2022-09-22 17:14:23'),
(200, 2704, 0, 5, 'Aline ', 'Aqwer@gmail.com', 'Ameiii, comprem sem medo, as coisas são maravilhosas', 'S', '172.71.10.81', '2022-09-22 17:15:16', '2022-09-22 17:15:16'),
