(2660, '17848', 'UN', '0', 111, 256, 168, 'Kit Argila Vermelha Controle de Oleosidade', 'Argila Vermelha Kit cuidados com a pele, absorve a oleosidade, hidrata, previne linhas de expressão, tem efeito cicatriz', '<p><strong><em><span style=\"font-size: large;\">Kit de argila Vermelha&nbsp; facial.</span></em></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Argilas Originais 100% Puras org&acirc;nicas e naturais ( sem corantes altificiais )</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Argila vermelha e aprovadas na Anvisa e com teste microbiol&oacute;gicos aprovados.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Seu rosto tem que ser BEM cuidado e com produtos SEGUROS.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O kit Skincare argila vermelha cont&eacute;m:</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Pacote de 100g da argila vermelha Ayanature</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Sabonete de limpeza facial (p&oacute;s maquiagem) pode ser utilizado para limpeza de pele Max Love</span></p>\r\n<p><span style=\"font-size: large;\">* 1 T&ocirc;nico Facial Max Love</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Sabonete P/pele oleosa acido Salic&iacute;lico Dermachem</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Mascara nutritiva noturna&nbsp; Max Love</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Gel Antissinais Booster 100G Dermachem</span></p>\r\n<p><span style=\"font-size: large;\">* 1 Pincel&nbsp; para aplica&ccedil;&atilde;o da argila.&nbsp;</span><span style=\"font-size: large;\">(Brinde)</span></p>\r\n<p>&nbsp;</p>', NULL, 58.99, NULL, NULL, 0.00, '', '', 0, 'N', NULL, 'N', 0, NULL, 'S', 'kit-argila-vermelha-controle-de-oleosidade', 'kit-argila-vermelha-controle-de-oleosidade', 'Kit Argila Vermelha Controle de Oleosidade', '2022-04-20 08:22:33', '2022-05-25 18:39:53', 26, 18, 9),
(2661, 'RT0700', 'UN', '0', 102, 241, 173, 'Shampoo Nutritivo Soul Coco 300ml', 'Shampoo Soul Coco com o poder do óleo de coco e Argan', '<p><strong><em><span style=\"font-size: large;\">Shampoo Nutritivo Soul Coco Retr&ocirc; Cosm&eacute;ticos 300ml</span></em></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O Shampoo Soul Coco traz os benef&iacute;cios da tradi&ccedil;&atilde;o e o PODER do &Oacute;LEO DE COCO, limpando e nutrindo os fios. Enriquecido com vitaminas E, K, lip&iacute;deos e prote&iacute;nas, o sensacional &Oacute;LEO DE COCO torna seus cabelos nutridos, previne pontas duplas, elimina frizz, fortalece, d&aacute; vida e movimento aos fios.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Benef&iacute;cios:</span></strong></p>\r\n<p><span style=\"font-size: large;\">-&nbsp; Cabelos nutridos</span></p>\r\n<p><span style=\"font-size: large;\">- Preven&ccedil;&atilde;o de Pontas duplas</span></p>\r\n<p>-&nbsp;&nbsp;<span style=\"font-size: large;\">Redu&ccedil;&atilde;o de Frizz</span></p>\r\n<p>-&nbsp;<span style=\"font-size: large;\">Aumento de brilho</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">ANVISA do produto: Shampoo Nutritivo Soul Coco Retr&ocirc; Cosm&eacute;ticos 300mL &ndash; Processo n&deg; 794679/2020-96.</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Modo de Uso:</span></strong></p>\r\n<p><span style=\"font-size: large;\">No cabelo molhado, aplique uma por&ccedil;&atilde;o generosa do Shampoo Soul Coco. Massageie o couro cabeludo e os fios em movimentos circulares vigorosos. Reaplique em caso de cabelos mais oleosos.</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Item Incluso:</span></strong></p>\r\n<p><span style=\"font-size: large;\">01 - Shampoo Nutritivo Soul Coco Retr&ocirc; Cosm&eacute;ticos 300ml</span></p>', 12.32, 18.30, NULL, NULL, 0.00, '', '', 0, 'N', 0.500, 'N', 0, NULL, 'S', 'shampoo-nutritivo-soul-coco-300ml', 'shampoo-nutritivo-soul-coco-300ml', 'Shampoo Nutritivo Soul Coco 300ml', '2022-04-22 10:54:35', '2025-03-08 11:56:19', 26, 18, 9),
