(2678, 'CL8-7', 'UN', '0', 78, 209, 185, 'Cílios Postiço Macrilan Volume Médio CL8-7', '', '<p><span style=\"color: #000000; font-size: large;\">C&iacute;lios posti&ccedil;os da Macrilan CL8-7 especialmente desenvolvidos para preencher, real&ccedil;ar e dar volume aos c&iacute;lios naturais com praticidade. Suas cerdas s&atilde;o extremamente macias, o que proporciona maior naturalidade e conforto, a base transparente al&eacute;m de n&atilde;o incomodar ainda d&aacute; acabamento ao encaixe dos c&iacute;lios. Garanta c&iacute;lios poderosos e conforto com a Macrilan,</span></p>', NULL, 12.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'cilios-postico-macrilan-volume-medio-cl8-7', 'cilios-postico-macrilan-volume-medio-cl8-7', 'Cílios Postiço Macrilan Volume Médio CL8-7', '2022-07-19 15:34:01', '2023-07-21 12:22:33', 16, 14, 6),
(2679, 'PI-2', 'UN', '0', 78, 209, 158, ' Pinca Para Sobrancelha Ponta Reta Profissional PI-2 Macrilan', '', '<p><span style=\"color: #000000; font-size: large;\">Pin&ccedil;a Macrilan PI-2</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Pin&ccedil;a Macrilan PI-2 especialmente desenvolvida para remo&ccedil;&atilde;o de pelos da face e corpo.Com acabamento dourado e corte reto para uso pessoal e profissional com praticidade e seguran&ccedil;a.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Especifica&ccedil;&atilde;o T&eacute;cnica</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Peso l&iacute;quido: 14,5 g</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Altura: 16 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Circunfer&ecirc;ncia: 14 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Modo de usar:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Agite antes de usar.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Utilize para remo&ccedil;&atilde;o de pelos da face e corpo.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Composi&ccedil;&atilde;o: A&ccedil;o carbono e pintura dourada.</span></p>', NULL, 15.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'pinca-para-sobrancelha-ponta-reta-profissional-pi-2-macrilan', 'pinca-para-sobrancelha-ponta-reta-profissional-pi-2-macrilan', ' Pinca Para Sobrancelha Ponta Reta Profissional PI-2 Macrilan', '2022-07-19 15:49:12', '2024-07-25 17:34:43', 16, 14, 6),
