(2681, '100294', 'UN', '0', 113, 209, 158, 'Pincel Dupla Função Chanfrado e ponta Palito', '', '<p><span style=\"color: #000000; font-size: large;\">O Pincel Dupla Fun&ccedil;&atilde;o Chanfrado e Ponta Palito Arte Sedu&ccedil;&atilde;o, &eacute; perfeito para aplica&ccedil;&atilde;o de Henna em sobrancelhas.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ponta Chanfrado perfeito para aplica&ccedil;&atilde;o de Henna</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ponta Palito ideal para aux&iacute;lio na limpesa.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Este pincel faz parte da linha Profissional de pinc&eacute;is Arte Sedu&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ideal para quem &eacute; profissional Designer de sobrancelha e tamb&eacute;m para quem est&aacute; come&ccedil;ando.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Resultado perfeito.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Feito com cerdas de pelo sint&eacute;tico sendo assim mais flex&iacute;vel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Virola c&ocirc;ncava met&aacute;lica, dando mais durabilidade ao seu pincel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cabo na cor preta de material reciclado&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Qualidade incompar&aacute;vel</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Limpeza e conserva&ccedil;&atilde;o:</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de &aacute;gua, lavar com &aacute;gua morna e sab&atilde;o neutro.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de solventes, limpar com thinner, enxugar e lavar com &aacute;gua e sab&atilde;o neutro.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Fabricado no Brasil</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cont&eacute;m 1 unidade</span></p>', NULL, 10.50, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'pincel-dupla-funcao-chanfrado-e-ponta-palito', 'pincel-dupla-funcao-chanfrado-e-ponta-palito', 'Pincel Dupla Função Chanfrado e ponta Palito', '2022-07-19 16:14:13', '2025-03-08 11:06:47', 16, 14, 6);
