(2682, '463960', 'UN', '0', 113, 209, 158, 'Pincel Dosador De Henna Para Sobrancelhas, Arte Sedução', '', '<p><span style=\"color: #000000; font-size: large;\">O Pincel Dosador de Henna para Sobrancelhas Arte Sedu&ccedil;&atilde;o, &eacute; perfeito para medir Henna e tinturas.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Este pincel faz parte da linha Profissional de pinc&eacute;is Arte Sedu&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ideal para quem para quem &eacute; profissional Designer de sobrancelha e tamb&eacute;m para quem est&aacute; come&ccedil;ando.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Resultado perfeito.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cabo na cor preta de material reciclado&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Qualidade incompar&aacute;vel</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Limpeza e conserva&ccedil;&atilde;o:</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de &aacute;gua, lavar com &aacute;gua morna e sab&atilde;o neutro.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de solventes, limpar com thinner, enxugar e lavar com &aacute;gua e sab&atilde;o neutro.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Fabricado no Brasil</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cont&eacute;m 1 unidade</span></p>', NULL, 8.90, NULL, NULL, 2.00, '', '', 0, 'S', 0.080, 'N', 0, NULL, 'N', 'pincel-dosador-de-henna-para-sobrancelhas-arte-seducao', 'pincel-dosador-de-henna-para-sobrancelhas-arte-seducao', 'Pincel Dosador De Henna Para Sobrancelhas, Arte Sedução', '2022-07-19 16:36:07', '2022-09-28 09:59:54', 16, 14, 6),
(2683, '463939', 'UN', '0', 113, 209, 158, 'Pincel Angular para Aplicação de Henna em Sobrancelhas ', '', '<p><span style=\"color: #000000; font-size: large;\">O Pincel para Henna Sobrancelha Angular Arte Sedu&ccedil;&atilde;o, &eacute; perfeito para aplica&ccedil;&atilde;o de Henna em sobrancelhas.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Este pincel faz parte da linha Profissional de pinc&eacute;is Arte Sedu&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ideal para quem &eacute; profissional Designer de sobrancelha e tamb&eacute;m para quem est&aacute; come&ccedil;ando.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Resultado perfeito.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Feito com cerdas de pelo sint&eacute;tico sendo assim mais flex&iacute;vel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Virola c&ocirc;ncava met&aacute;lica, dando mais durabilidade ao seu pincel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cabo na cor preta de material reciclado&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Qualidade incompar&aacute;vel</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Limpeza e conserva&ccedil;&atilde;o:</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de &aacute;gua, lavar com &aacute;gua morna e sab&atilde;o neutro.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de solventes, limpar com thinner, enxugar e lavar com &aacute;gua e sab&atilde;o neutro.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Fabricado no Brasil</span></p>', NULL, 10.20, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'pincel-angular-para-aplicacao-de-henna-em-sobrancelhas', 'pincel-angular-para-aplicacao-de-henna-em-sobrancelhas', 'Pincel Angular para Aplicação de Henna em Sobrancelhas ', '2022-07-19 16:50:23', '2025-02-22 09:44:55', 16, 14, 6),
(2684, 'FP001-1', 'UN', '0', 114, 209, 157, 'Esponja para maquiagem Hello Mini', '', '<p><span style=\"font-size: large; color: #000000;\">Kit de Esponjas Queijinho Hello Mini FP001</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large; color: #000000;\">S&atilde;o 8 Esponjas para maquiagem com qualidade profissional !&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large; color: #000000;\">Especifica&ccedil;&otilde;es:</span></p>\r\n<p><span style=\"font-size: large; color: #000000;\">Tamanho do produto (unit&aacute;rio): 8,0cm de di&acirc;metro x 1,5cm de altura</span></p>\r\n<p><span style=\"font-size: large; color: #000000;\">Material: Latex</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', NULL, 9.99, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'esponja-para-maquiagem-hello-mini', 'esponja-para-maquiagem-hello-mini', 'Esponja para maquiagem Hello Mini', '2022-07-19 17:06:32', '2022-09-23 16:16:36', 16, 14, 6),
(2685, 'RL03', 'UN', '0', 114, 209, 157, 'Pincel Angular Para Henna Em Sobrancelha, Arte Sedução', '', '<p><span style=\"font-size: large;\">ESPONJA PARA MAQUIAGEM HELLO MINI RL02</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large; color: #ff0000;\">A Cor &eacute;&nbsp; enviada conforme disponivel no estoque&nbsp;</span></p>\r\n<p><span style=\"font-size: large;\">A Esponja para Maquiagem &ndash; Hello Mini &eacute; feita especialmente para quem busca facilidade e praticidade na hora de aplicar produtos cremosos e/ou l&iacute;quidos na pele, proporciona um acabamento natural e uniforme &agrave; sua maquiagem.</span></p>\r\n<p><span style=\"font-size: large;\">Sua ponta com design mais fino ajuda a alcan&ccedil;ar lugares mais dif&iacute;ceis e sua base mais arredondada facilita na aplica&ccedil;&atilde;o de produtos em todo o rosto.</span></p>\r\n<p><span style=\"font-size: large;\">Possui textura macia e suave.</span></p>\r\n<p><span style=\"font-size: large;\">A esponja cont&eacute;m L&aacute;tex o que faz com que ao ser molhada ela incha e absorva menos produto.</span></p>', NULL, 8.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'NAME', 'NAME', 'Pincel Angular Para Henna Em Sobrancelha, Arte Sedução', '2022-07-19 17:23:33', '2022-09-28 09:57:55', 16, 14, 6),
(2686, '34036001002', 'UN', '0', 85, 217, 155, 'Água Micelar com Carvão Ativado', 'Água MIcelar com carvão ativado para uma limpeza mais profunda', '<p style=\"margin: 0px; font-size: 14px;\"><strong><em>Max Love Carv&atilde;o Ativado</em></strong></p>\r\n<p style=\"margin: 0px; font-size: 14px;\">&nbsp;</p>\r\n<p style=\"margin: 0px; font-size: 14px;\">&Aacute;gua Micelar para todos os tipos de pele. Carv&atilde;o Ativado Max Love foi desenvolvida para promover uma limpeza facial suave, removendo toda maquiagem e impurezas sem agredir a pele.</p>\r\n<p style=\"margin: 0px; font-size: 14px;\">&nbsp;</p>\r\n<p style=\"margin: 0px; font-size: 14px;\">&nbsp;</p>\r\n<p style=\"margin: 0px; font-size: 14px;\">&nbsp;</p>\r\n<p style=\"margin: 0px; font-size: 14px;\">A &Aacute;gua Micelar Carv&atilde;o Ativado Max Love &eacute; enriquecida com Carv&atilde;o Ativado e outros extratos naturais para proporcionar limpeza profunda, com a&ccedil;&atilde;o purificante, e sensa&ccedil;&atilde;o de frescor. Livre de parabenos e petrolatos.</p>', NULL, 17.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.450, 'N', 0, NULL, 'N', 'Agua-micelar-com-carvao-ativado', 'Agua-micelar-com-carvao-ativado', 'Água Micelar com Carvão Ativado', '2022-07-22 07:39:14', '2023-10-03 11:38:17', 23, 34, 12),
(2687, 'M136', 'UN', '0', 78, 209, 153, 'Pincel Macrilan M136 Duplo Escova e Chanfrado para Maquiagem', '', '<p><span style=\"font-size: large;\">Pincel Profissional Duplo Escova e Chanfrado Macrilan M-136 Pincel Duplo Macrilan de um lado com formato Chanfrado ideal para definir e preencher sobrancelhas e tamb&eacute;m para delinear a linha dos c&iacute;lios e a linha d\'&aacute;gua. Do outro lado com formato Escova, perfeito para pentear alinhar os fios das sobrancelhas e retirar o excesso de m&aacute;scara dos c&iacute;lios.Feito com Cerdas sint&eacute;ticas especiais e com um design que facilita a aplica&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: medium;\">Comprimento: 18cm C</span></p>\r\n<p><span style=\"font-size: medium;\">Largura: 0,5</span></p>\r\n<p><span style=\"font-size: medium;\">Cerdas:&nbsp; Sint&eacute;ticas</span></p>\r\n<p><span style=\"font-size: medium;\">Cabo: Madeira</span></p>\r\n<p><span style=\"font-size: medium;\"><br /></span></p>', NULL, 10.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'pincel-macrilan-m136-duplo-escova-e-chanfrado-para-maquiagem', 'pincel-macrilan-m136-duplo-escova-e-chanfrado-para-maquiagem', 'Pincel Macrilan M136 Duplo Escova e Chanfrado para Maquiagem', '2022-07-22 11:22:18', '2024-07-25 17:58:57', 16, 14, 6),
(2688, 'CU11-012', 'UN', '0', 115, 209, 184, 'Curvador de cílios - Miss Frandy ', '', '<p><span style=\"font-size: large;\">O curvex de c&iacute;lios da Miss Frandy &eacute; especialmente utilizado para modelar os c&iacute;lios durante a maquiagem,ele curva sem danificar os fios, dando o efeito alongado que amamos. O curvex &eacute; um charme, pois possui uma patinha de cachorro super fofinha!</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\">Material</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: medium;\">Estrutura de metal&nbsp;</span></p>\r\n<p><span style=\"font-size: medium;\">Pegador de ap&oacute;io para os dedos de plastico cor Roxo</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>', NULL, 10.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'curvador-de-cilios-miss-frandy', 'curvador-de-cilios-miss-frandy', 'Curvador de cílios - Miss Frandy ', '2022-07-22 12:20:57', '2025-09-10 19:17:04', 16, 14, 6),
(2689, 'FTP001', 'UN', '0', 58, 209, 170, 'Pincel Silicone Para  Aplicação de Argilas e Cremes Faciais de Skincare', '', '<p><span style=\"font-size: large;\">Pincel de Silicone para SkinCare</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">N&Atilde;O &Eacute; POSS&Iacute;VEL ESCOLHER A COR, enviaremos confome disponibilidade</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Pincel em silicone indicado para aplica&ccedil;&atilde;o de produtos no rosto, tais como m&aacute;scaras faciais, cremes, argila ou at&eacute; mesmo base.</span></p>\r\n<p><span style=\"font-size: large;\">O silicone n&atilde;o absorve o produto permitindo um melhor aproveitamento do mesmo.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Limpeza e conserva&ccedil;&atilde;o:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">- Lave a ponta de silicone com &aacute;gua fria e sabonete neutro.</span></p>\r\n<p><span style=\"font-size: large;\">- Seque com uma toalha macia.</span></p>\r\n<p><span style=\"font-size: large;\">- O cabo n&atilde;o deve ser molhado ou permanecer &uacute;mido</span></p>\r\n<p><span style=\"font-size: large;\">- Use apenas um pano seco para sua limpeza.</span></p>\r\n<p><span style=\"font-size: large;\">- N&atilde;o deixe seus pinc&eacute;is de molho.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Material: Silicone (ponta)</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Cores conforme estoque</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Cont&eacute;m:</span></p>\r\n<p><span style=\"font-size: large;\">1uni Pincel Silicone</span></p>\r\n<div>&nbsp;</div>', NULL, 8.90, NULL, NULL, 7.00, '', '', 0, 'S', 0.100, 'N', 0, NULL, 'N', 'pincel-silicone-para-aplicacao-de-argilas-e-cremes-faciais-de-skincare', 'pincel-silicone-para-aplicacao-de-argilas-e-cremes-faciais-de-skincare', 'Pincel Silicone Para  Aplicação de Argilas e Cremes Faciais de Skincare', '2022-07-22 14:36:12', '2025-04-24 10:54:11', 16, 14, 6),
(2690, '7896025503090', 'UN', '0', 112, 209, 177, 'Kit Pente de Bolso com duas Unidades  Marco Boni', '', '<p><span style=\"font-size: large;\">O Pente Masculino de Bolso da Marco Boni possui as seguintes medidas: </span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\">Comprimento: 127 mm; Largura: 32 mm; Altura: 5 mm.</span></p>', NULL, 11.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'kit-pente-de-bolso-com-duas-unidades-marco-boni', 'kit-pente-de-bolso-com-duas-unidades-marco-boni ', 'Kit Pente de Bolso com duas Unidades  Marco Boni', '2022-07-22 15:21:37', '2025-03-08 11:07:04', 16, 14, 6),
(2691, '549BT', 'UN', '0', 112, 209, 177, 'Escova de Cabelo Raquete Almofadada Top Color Oval Linha Bonitta da Marco Boni 549BT - BONITA', '', '<p><span style=\"font-size: large;\">Escova de Cabelo Raquete Almofadada Top Color Oval Linha Bonitta da Marco Boni 549BT</span></p>\r\n<p><span style=\"font-size: large;\">Cerdas flex&iacute;veis com pontas arredondadas</span></p>\r\n<p><span style=\"font-size: large;\">Escova de uso di&aacute;rio</span></p>\r\n<p><span style=\"font-size: large;\">Almofadada, indicada para pentear e desembara&ccedil;ar os cabelos</span></p>\r\n<p><span style=\"font-size: large;\">N&atilde;o agride os fios.Produto ORIGINAL da Linha Bonitta da Marco Boni e fotos reais.</span></p>', NULL, 25.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.200, 'N', 0, NULL, 'N', 'escova-de-cabelo-raquete-almofadada-top-color-oval-linha-bonitta-da-marco-boni-549bt-bonita', 'escova-de-cabelo-raquete-almofadada-top-color-oval-linha-bonitta-da-marco-boni-549bt-bonita', 'Escova de Cabelo Raquete Almofadada Top Color Oval Linha Bonitta da Marco Boni 549BT - BONITA', '2022-07-22 15:55:15', '2025-03-08 11:07:20', 26, 14, 16),
(2692, '502BT', 'UN', '0', 112, 209, 177, 'Escova De Cabelo Bonitta Retagular Uso Diario Basico', '', '<p><span style=\"font-size: large;\">Escova pl&aacute;stica perfeita para desembara&ccedil;ar sem quebrar os fios. Suas cerdas macias evitam machucar o couro cabeludo dando maior confian&ccedil;a na hora da escova&ccedil;&atilde;o.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Modo de uso:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Passe suavemente as cerdas pelo cabelo.</span></p>', NULL, 13.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'escova-de-cabelo-bonitta-retagular-uso-diario-basico', 'escova-de-cabelo-bonitta-retagular-uso-diario-basico', 'Escova De Cabelo Bonitta Retagular Uso Diario Basico', '2022-07-22 16:08:52', '2025-03-08 11:07:38', 16, 14, 6),
(2693, '502BTR', 'UN', '0', 112, 209, 177, 'Escova De Cabelo Bonitta Retagular Uso Diario Basico Rosa', '', '<p><span style=\"font-size: large;\">Escova pl&aacute;stica perfeita para desembara&ccedil;ar sem quebrar os fios. Suas cerdas macias evitam machucar o couro cabeludo dando maior confian&ccedil;a na hora da escova&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"font-size: large;\">Modo de uso:</span></p>\r\n<p><span style=\"font-size: large;\">Passe suavemente as cerdas pelo cabelo.</span></p>', NULL, 13.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'escova-de-cabelo-bonitta-retagular-uso-diario-basico-cor-rosa', 'escova-de-cabelo-bonitta-retagular-uso-diario-basico-cor-rosa', 'Escova De Cabelo Bonitta Retagular Uso Diario Basico Rosa', '2022-07-22 16:11:45', '2024-07-25 18:03:22', 16, 14, 6),
(2694, '104377', 'UN', '0', 113, 209, 177, 'Kit 3 Pentes de Plástico para Cabelos Pequeno Médio Grande - Arte Sedução', '', '<p><span style=\"font-size: large;\">01 - Kit 3 Pentes de Pl&aacute;stico para Cabelos Pequeno M&eacute;dio Grande</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Os pentes de pl&aacute;stico possuem diversos usos e s&atilde;o indicados para pentear e desembara&ccedil;ar cabelos molhados por serem resistentes, de f&aacute;cil secagem e evitarem a prolifera&ccedil;&atilde;o de bact&eacute;rias. S&atilde;o inclusos 3 pentes de diferentes tamanhos e espa&ccedil;amento entre os dentes, sendo eles pequeno, m&eacute;dio e grande. Os pentes com pouco espa&ccedil;o entre os dentes s&atilde;o indicados para cabelos lisos devido a maior proximidade com os fios que faz com que eles sejam esticados. J&aacute; os de maior espa&ccedil;amento, s&atilde;o indicados para cabelos ondulados os deixando com movimento e apar&ecirc;ncia natural e para cacheados e crespos facilitando o desembara&ccedil;ar sem danificar os cachos.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Medidas (AxL):</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Pente P - 20 cm x 3 cm</span></p>\r\n<p><span style=\"font-size: large;\">Pente M - 22,5 cm x 4,5 cm</span></p>\r\n<p><span style=\"font-size: large;\">Pente G - 22,5 cm x 5,5 cm</span></p>', NULL, 12.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'kit-3-pentes-de-plastico-para-cabelos-pequeno-medio-grande-arte-seducao', 'kit-3-pentes-de-plastico-para-cabelos-pequeno-medio-grande-arte-seducao', 'Kit 3 Pentes de Plástico para Cabelos Pequeno Médio Grande - Arte Sedução', '2022-07-22 16:26:26', '2025-03-08 11:08:04', 22, 15, 6),
(2695, '626BT', 'UN', '0', 112, 209, 177, 'Touca para Banho  29 cm  1 Unidades - Bonitta - Ref.627 - Marco Boni ', '', '<p><span style=\"font-size: large;\">Usos recomendados: Reutiliz&aacute;vel e imperme&aacute;vel,proteja seu cabelo de se molhar. Volume pequeno e dobr&aacute;vel,leve,f&aacute;cil de transportar durante viagens e viagens. Com el&aacute;stico,adequado para diferentes circunfer&ecirc;ncias da cabe&ccedil;a,tamanho &uacute;nico para a maioria das pessoas.</span></p>', NULL, 5.50, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'touca-para-banho-29-cm-1-unidades-bonitta-ref-627-marco-boni', 'touca-para-banho-29-cm-1-unidades-bonitta-ref-627-marco-boni', 'Touca para Banho  29 cm  1 Unidades - Bonitta - Ref.627 - Marco Boni ', '2022-07-22 16:36:24', '2024-07-25 18:04:47', 16, 14, 6),
(2696, 'TBA11', 'UN', '0', 60, 250, 177, 'Touca de Cetim Seda Dormir Banho Anti Frizz Hidrata Cabelo', 'Descubra o segredo para cabelos incríveis! Adquira já nossa Touca de Cetim e Seda, a solução anti-frizz que hidrata durante o sono. Transforme seus fios agora!', '<p><span style=\"font-size: large;\">Toca / touca De Cetim Seda&nbsp; Anti Frizz</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Esse an&uacute;ncio &eacute; para 1 toca de cetim</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">ENVIO SORTIDO DAS CORES</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">(enviamos a touca de acordo com a disponibilidade de cor do nossos estoques no momento, n&atilde;o podendo o cliente escolher a cor da touca)</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Reduz o frizz</span></strong></p>\r\n<p><span style=\"font-size: large;\">Reduz a queda do cabelo e tamb&eacute;m a quebra dos fios</span></p>\r\n<p><span style=\"font-size: large;\">Reduz a absor&ccedil;&atilde;o da umidade natural dos cabelos, reduzindo o ressecamento dos fios</span></p>\r\n<p><span style=\"font-size: large;\">Garante mais day after</span></p>\r\n<p><span style=\"font-size: large;\">Utilize sempre o lado brilhante para dentro</span></p>\r\n<p><span style=\"font-size: large;\">Indicado para todos os tipos de cabelos</span></p>', NULL, 10.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.100, 'N', 0, NULL, 'N', 'touca-de-cetim-seda-dormir-banho-anti-frizz-hidrata-cabelo', 'touca-de-cetim-seda-dormir-banho-anti-frizz-hidrata-cabelo', 'Touca de Cetim Seda Dormir Banho Anti Frizz Hidrata Cabelo', '2022-07-22 16:56:36', '2025-02-21 14:08:05', 16, 14, 6),
(2697, '1783', 'UN', '0', 112, 209, 158, 'Paquímetro Para Sobrancelha Branco Com 1 Unidade Marco Boni', '', '<p><span style=\"font-size: large;\">Imagens meramente ilustrativas.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Auxilia na realiza&ccedil;&atilde;o do procedimento de design de sobrancelhas. Ajuda nas medidas e nas distncias de cada parte dela e deix&aacute;-la em simetria. Auxilia na hora de medir as distncias de cada parte dela e deix&aacute;-la em simetria. Possui trava.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">CARACTER&Iacute;STICAS DO PRODUTO</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\">- Auxilia na realiza&ccedil;&atilde;o do procedimento de design de sobrancelhas.</span></p>\r\n<p><span style=\"font-size: large;\">- Ajuda nas medidas e nas distncias de cada parte dela e deix&aacute;-la em simetria.</span></p>\r\n<p><span style=\"font-size: large;\">- Auxilia na hora de medir as distncias de cada parte dela e deix&aacute;-la em simetria.</span></p>\r\n<p><span style=\"font-size: large;\">- Possui trava.</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\">Tipo do Material: Pl&aacute;stico refor&ccedil;ado</span></p>', NULL, 16.90, NULL, NULL, 2.00, '', '', 0, 'S', 0.100, 'N', 0, NULL, 'N', 'paquimetro-para-sobrancelha-branco-com-1-unidade-marco-boni', 'paquimetro-para-sobrancelha-branco-com-1-unidade-marco-boni', 'Paquímetro Para Sobrancelha Branco Com 1 Unidade Marco Boni', '2022-07-22 17:08:42', '2022-09-28 09:34:24', 32, 18, 6),
(2698, 'HB-305', 'UN', '0', 87, 85, 169, 'Água Termal Fragrância Coco 150ml', 'Água Termal Rosa Fragrância de Coco Ruby Rose', '<p><em><strong><span style=\"font-size: large;\">&Aacute;gua Termal Ruby Rose Fragr&acirc;ncia de Coco Ruby Rose 150ml</span></strong></em></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">A &Aacute;gua Termal da Ruby Rose foi produzida especialmente para hidratar, suavizar e deixar sua pele radiante. O uso di&aacute;rio suaviza os tra&ccedil;os, minimiza os poros e proporciona luminosidade a sua pele. O produto possui a&ccedil;&atilde;o refrescante antes e na hora da aplica&ccedil;&atilde;o. Uma de suas caracter&iacute;sticas marcantes &eacute; a maravilhosa fragr&acirc;ncia de coco.</span></p>\r\n<p><span style=\"font-size: large;\">Fragr&acirc;ncia: Coco</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Modo de Uso:</span></strong></p>\r\n<p><span style=\"font-size: large;\">Agite antes de usar. </span></p>\r\n<p><span style=\"font-size: large;\">Aplique&nbsp; 15cm de dist&acirc;ncia do local de aplica&ccedil;&atilde;o.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Sugest&otilde;es de uso:</span></strong></p>\r\n<p><span style=\"font-size: large;\">- Para fixar maquiagem.</span></p>\r\n<p><span style=\"font-size: large;\">- Para acalmar pele irritada</span></p>\r\n<p><span style=\"font-size: large;\">- Hidrata&ccedil;&atilde;o e brilho do couro cabeludo</span></p>\r\n<p><span style=\"font-size: large;\">- P&oacute;s-sol para aliviar sensa&ccedil;&atilde;o de queimaduras</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Dimens&otilde;es:</span></strong></p>\r\n<p><span style=\"font-size: large;\">Medidas do produto fechado (unit&aacute;rio): 4,3cm de di&acirc;metro; 17,0cm de altura;</span></p>\r\n<p><span style=\"font-size: large;\">Peso L&iacute;quido (unit&aacute;rio): 150ml</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Cont&eacute;m: 1 unidade</span></strong></p>', NULL, 15.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.200, 'N', 0, NULL, 'S', 'Agua-termal-fragrancia-coco-150ml', 'Agua-termal-fragrancia-coco-150ml', 'Água Termal Fragrância Coco 150ml', '2022-08-19 07:07:35', '2024-07-25 18:01:02', 23, 15, 6),
(2699, 'HB8219241', 'UN', '0', 87, 85, 150, 'Batom Liquido Metalizado Metalicool Cor 241', 'Batom Liquido com acabamento metalizado cor vinho Ruby Rose', '<p><span style=\"font-size: large;\">A linha do Metalicool tem efeito Metalizado e suas cores cont&eacute;m alta cobertura para voc&ecirc; expressar de forma aut&ecirc;ntica a sua personalidade, atrav&eacute;s das cores que variam entre neutras, vibrantes e intensas. Por ser l&iacute;quido ele garante um efeito marcante e duradouro, a secagem &eacute; r&aacute;pida fazendo com que o resultado final seja perfeito.</span></p>\r\n<p><span style=\"font-size: large;\">EFEITO Met&aacute;lico</span></p>\r\n<p><span style=\"font-size: large;\">TEXTURA&nbsp; L&iacute;quida</span></p>\r\n<p><span style=\"font-size: large;\">CERTIFICA&Ccedil;&Otilde;ES Cruelty Free</span></p>\r\n<p><span style=\"font-size: large;\">Imagem Meramente Ilustrativa</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">OBSERVA&Ccedil;&Otilde;ES</span></strong></p>\r\n<p><span style=\"font-size: large;\">G&Ecirc;NERO Unissex</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">ITENS INCLUSOS</span></strong></p>\r\n<p><span style=\"font-size: large;\">1 Batom L&iacute;quido Met&aacute;lico Ruby Rose Metalicool Burgundy 241 4,5 ml</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><em><span style=\"font-size: large;\">LINHA Metalicool</span></em></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\"><strong>TAMANHO DA EMBALAGEM</strong> Regular</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\"><strong>MATERIAL DA EMBALAGEM</strong> Pl&aacute;stico</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\"><strong>COMPOSI&Ccedil;&Atilde;O</strong><br /></span><span style=\"font-size: large;\">Isododecane, Ethylene/Propylene/Styrene Copolymer, Ceresin, Cyclopentasiloxane, Hydrated Silica, Caprylic/ Capric Triglyceride, Paraffinum Liquidum, Mica, Parfum, Cinnamyl Alcohol, limonene, Linalool</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Pode conter: Mica, Tin Oxide, CI 77491, CI 77891, CI 45410, CI 15850, CI 77492, CI 19140, CI 42090, CI 15985, CI 17200, CI 75470., Isododecane, Ethylene/Propylene/Styrene Copolymer, Ceresin, Cyclopentasiloxane, Hydrated Silica, Caprylic/ Capric Triglyceride, Paraffinum Liquidum, Mica, Parfum, Cinnamyl Alcohol, limonene, Linalool</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Pode conter: Mica, Tin Oxide, CI 77491, CI 77891, CI 45410, CI 15850, CI 77492, CI 19140, CI 42090, CI 15985, CI 17200, CI 75470.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">SUGEST&Atilde;O DE USO</span></strong></p>\r\n<p><span style=\"font-size: large;\">1. Comece aplicando do canto em dire&ccedil;&atilde;o ao centro dos l&aacute;bios;</span></p>\r\n<p><span style=\"font-size: large;\">2. Finalize preenchendo a parte interna deixando-o uniforme., </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\"><strong>PRECAU&Ccedil;&Otilde;ES</strong> <br />1. Uso externo;</span></p>\r\n<p><span style=\"font-size: large;\">2. Manter fora do alcance de crian&ccedil;as;</span></p>\r\n<p><span style=\"font-size: large;\">3. Manter longe da luz e calor excessivo.</span></p>\r\n<p>&nbsp;</p>', NULL, 12.00, NULL, NULL, 0.00, '', '', 0, 'N', 0.150, 'N', 0, NULL, 'N', 'batom-liquido-metalizado-metalicool-cor-241', 'batom-liquido-metalizado-metalicool-cor-241', 'Batom Liquido Metalizado Metalicool Cor 241', '2022-08-26 07:46:26', '2023-06-22 18:13:54', 16, 14, 6),
(2700, '507361', 'UN', '0', 85, 217, 148, 'Máscara para cílios Flower  02', 'Máscara de Cílios Max Love para Alongamento com aspecto natural', '<p><span style=\"font-size: large;\">A linha de m&aacute;scaras de c&iacute;lios Flower na cor preta, conta com f&oacute;rmula enriquecida com Manteiga de Karit&eacute;, &Oacute;leo de Argan, D\'Pantenol e Vitamina E que auxilia na hidrata&ccedil;&atilde;o dos fios dos c&iacute;lios. Al&eacute;m disso, &eacute; livre de parabenos e petrolatos. O pincel 02 proporciona <strong><em>alongamento com visual natural.</em></strong></span></p>', NULL, 12.80, NULL, NULL, 0.00, '', '', 0, 'N', 0.150, 'N', 0, NULL, 'S', 'mascara-para-cilios-flower-02', 'mascara-para-cilios-flower-02', 'Máscara para cílios Flower  02', '2022-08-26 08:05:04', '2023-08-03 18:15:11', 16, 14, 6),
(2701, 'L887-B', 'UN', '0', 116, 250, 145, 'Lápis para olho preto com apontador Luisance', '', '<p><span style=\"font-size: large;\">Luisance Preto</span></p>\r\n<p><span style=\"font-size: large;\">L&aacute;pis de olho com apontador acoplado. Luisance destaca o olhar com delineado preciso e de longa dura&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"font-size: large;\">L&aacute;pis de Olho Luisance com Apontador &eacute; ideal para quem gosta de um olhar marcante. Possui um design especial que mant&eacute;m a ponta perfeita para o uso, e al&eacute;m de tudo j&aacute; vem com um apontador na tampa para garantir ainda mais praticidade.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Como Usar</span></p>\r\n<p><span style=\"font-size: large;\">Conselho de Aplica&ccedil;&atilde;o</span></p>\r\n<p><span style=\"font-size: large;\">Fa&ccedil;a um tra&ccedil;o fino rente aos c&iacute;lios para criar um delineado ou passe sobre a linha d\'&aacute;gua.&nbsp;</span></p>\r\n<p><span style=\"font-size: large;\">Se quiser criar um efeito esfumado, use um pincel chanfrado logo ap&oacute;s a aplica&ccedil;&atilde;o.&nbsp;</span></p>', 2.06, 3.80, NULL, NULL, 0.00, '', '', 0, 'N', 0.090, 'N', 0, NULL, 'N', 'lapis-para-olho-preto-com-apontador-luisance', 'lapis-para-olho-preto-com-apontador-luisance', 'Lápis para olho preto com apontador Luisance', '2022-08-27 17:29:30', '2023-11-23 19:12:59', 16, 14, 5),
(2702, '215210', 'UN', '0', 85, 217, 141, 'Pó Compacto Matte HD Banana 354 Max Love Original', '', '<p><span style=\"font-size: large;\">&nbsp;P&oacute; Compacto Matte HD Banana Max Love cont&eacute;m micropart&iacute;culas que proporcionam uma cobertura suave da pele, minimizando o brilho e garantindo uma finaliza&ccedil;&atilde;o ultrafina de longa dura&ccedil;&atilde;o.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Sua f&oacute;rmula livre de &oacute;leo (oil-free) n&atilde;o mancha, n&atilde;o transfere e n&atilde;o obstrui os poros, permitindo que a pele respire livremente.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O P&oacute; &eacute; indicado para selar a maquiagem fazendo com que a mesma dure mais tempo e deixa o rosto com aspecto aveludado.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Indicado para todos os tons de pele.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O P&oacute; Banana tem o poder de auxiliar no controle da oleosidade da pele. Voc&ecirc; inclusive pode dar preferencia a zona T (testa, nariz e queixo) que &eacute; onde normalmente ela se concentra. Como resultado voc&ecirc; ganha uma pele com efeito matte.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Modo de usar: Passe a esponja ou o pincel sobre o produto e aplique levemente no rosto de maneira uniforme.</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', NULL, 11.80, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'po-compacto-matte-hd-banana-354-max-love-original', 'po-compacto-matte-hd-banana-354-max-love-original', 'Pó Compacto Matte HD Banana 354 Max Love Original', '2022-09-01 14:53:29', '2024-07-25 17:59:34', 16, 14, 5),
(2703, '215258', 'UN', '0', 85, 217, 119, 'Pó Compacto Matte HD Translúcido 35 Max Love Original', '', '<p><span style=\"font-size: large;\">O P&oacute; Compacto Matte HD Transl&uacute;cido 35 Max Love cont&eacute;m micropart&iacute;culas que proporcionam uma cobertura suave da pele, minimizando o brilho e garantindo uma finaliza&ccedil;&atilde;o ultrafina de longa dura&ccedil;&atilde;o.&nbsp;</span></p>\r\n<p><span style=\"font-size: large;\">Sua f&oacute;rmula livre de &oacute;leo (oil-free) n&atilde;o mancha, n&atilde;o transfere e n&atilde;o obstrui os poros, permitindo que a pele respire livremente.</span></p>\r\n<p><span style=\"font-size: large;\">O P&oacute; &eacute; indicado para selar a maquiagem fazendo com que a mesma dure mais tempo e deixa o rosto com aspecto aveludado.</span></p>\r\n<p><span style=\"font-size: large;\">O P&oacute; Transl&uacute;cido serve para todos os tons de pele e, entre as suas principais fun&ccedil;&otilde;es, est&aacute; a de garantir o acabamento da maquiagem ajudando a fix&aacute;-la e a retirar o brilho causado pela oleosidade.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">N&atilde;o podemos esquecer que ele d&aacute; um efeito bem mais natural ap&oacute;s a aplica&ccedil;&atilde;o da base e do corretivo.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Modo de usar: Passe a esponja ou o pincel sobre o produto e aplique levemente no rosto de maneira uniforme.</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">- Cont&eacute;m: 01 P&oacute; Compacto Matte HD Transl&uacute;cido 35.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">- Marca: Max Love.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">- Imagens ilustrativas.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">- PRODUTO N&Atilde;O TESTADO EM ANIMAIS.</span></p>', NULL, 12.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'po-compacto-matte-hd-translucido-35-max-love-original', 'po-compacto-matte-hd-translucido-35-max-love-original', 'Pó Compacto Matte HD Translúcido 35 Max Love Original', '2022-09-01 15:47:56', '2023-09-08 16:23:50', 16, 14, 5),
(2704, 'DL084503N', 'UN', '0', 90, 188, 138, 'Base 3N Líquida de Alta Cobertura My Secret', '', '<p><span style=\"font-size: large;\">A Dalla traz uma base que &eacute; um verdadeiro presente para voc&ecirc;! A Base My Secret Cor 01 &eacute; a base de alta performance que voc&ecirc; esperava com alta cobertura efeito matte que uniformiza a pele, alta durabilidade, resistente a &aacute;gua e ao suor. Al&eacute;m disso, sua f&oacute;rmula cont&eacute;m um componente hidratante que contribui para restabelecer os n&iacute;veis de &aacute;gua na pele que protege e preserva sua elasticidade tudo isso em uma embalagem linda e presente&aacute;vel.</span></p>\r\n<p><span style=\"font-size: large;\">Porque voc&ecirc; vai amar a Base My Secret:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">* Efeito matte</span></p>\r\n<p><span style=\"font-size: large;\">* Produto vegano e n&atilde;o testado em animais</span></p>\r\n<p><span style=\"font-size: large;\">* Livre de &oacute;leos e parabenos</span></p>\r\n<p><span style=\"font-size: large;\">* Resistente &agrave; &aacute;gua</span></p>\r\n<p><span style=\"font-size: large;\">* Longa dura&ccedil;&atilde;o</span></p>\r\n<p><span style=\"font-size: large;\">Cont&eacute;m: 35mL em uma embalagem frasco pump com tampa.</span></p>\r\n<p><span style=\"font-size: large;\">Modo de usar: Aplique sobre o rosto com aux&iacute;lio de pincel ou esponja em movimentos circulares, at&eacute; obter o resultado desejado.</span></p>\r\n<p><span style=\"font-size: large;\">Precau&ccedil;&otilde;es: Manter fora do alcance das crian&ccedil;as. Em caso de eventual sensibilidade suspender o uso. Uso externo.</span></p>\r\n<p><span style=\"font-size: large;\">Composi&ccedil;&atilde;o: Cyclomethicone/Ciclometicona, Isododecane/Isododecano, Trimethylsiloxysilicate/Trimetilsiloxissilicato, Dimethicone/Dimeticona, Magnesium Stearate/Estearato de Magn&eacute;sio, Dimethicone Crosspolymer/Crospol&iacute;mero de Dimeticona, Lauryl PEG-10 Tris(Trimethylsiloxt)Silyethyl Dimethicone/Lauril PEG-10 Tris(Trimetilsiloxi)Sililetil Dimeticona, Aluminum Starch Octenylsuccinate/Amidoctenilsuccinato de Alum&iacute;nio, Talc/Talco, Kaolin/Caulim, Aqua/&Aacute;gua, Glycerin/Glicerol, Sodium Chloride/Cloreto de S&oacute;dio, Disodium EDTA/Edetato Diss&oacute;dico, Phenoxyethanol/Fenoxietanol, Caprylyl Glycol/Caprililglicol, Silica/Di&oacute;xido de Sil&iacute;cio. Pode conter: Aluminum Dimyristate/Dimiristato de Alum&iacute;nio, Triethoxycaprylylsilane/ Trietoxicaprililsilano, Disodium Stearoyl Glutamate/Estearoil Glutamato Diss&oacute;dico e os corantes: CI77891/Di&oacute;xido de Tit&acirc;nio, CI77499/&Oacute;xido de Ferro Preto, CI77492/&Oacute;xido de Ferro Amarelo, CI77491/&Oacute;xido de Ferro Vermelho, CI77288/Verde.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">*As cores do produto podem variar conforme a configura&ccedil;&atilde;o do seu monitor/celular.</span></p>\r\n<div class=\"resp-container\"><iframe class=\"resp-iframe\" title=\"YouTube video player\" src=\"https://www.youtube.com/embed/v4JJECRWaUs\" frameborder=\"0\"></iframe></div>', 22.85, 49.80, NULL, NULL, 0.00, '', '', 0, 'N', 0.150, 'N', 0, NULL, 'N', 'base-3n-liquida-de-alta-cobertura-my-secret', 'base-3n-liquida-de-alta-cobertura-my-secret', 'Base 3N Líquida de Alta Cobertura My Secret', '2022-09-06 16:16:49', '2023-09-08 16:28:41', 17, 12, 11),
