(3080, '002324', 'UN', '0', 137, 2, 157, 'Pote de esponja com 12 unidades', 'Pote com 12 esponjas macias para uma make impecável! Perfeito para base, corretivo e pó. Compre agora e garanta um acabamento profissional!', '<p><span style=\"font-size: large;\">Garanta uma aplica&ccedil;&atilde;o impec&aacute;vel com o <strong>Pote de Esponjas com 12 Unidades</strong>! Perfeito para maquiagem l&iacute;quida, cremosa ou em p&oacute;, esse kit oferece esponjas macias e vers&aacute;teis para um acabamento uniforme e natural.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O <strong>pote pr&aacute;tico</strong> mant&eacute;m as esponjas protegidas e organizadas, facilitando o transporte e armazenamento. Ideais para aplicar base, corretivo, p&oacute; e at&eacute; mesmo esfumados, essas esponjas garantem uma make sem marcas e com aspecto profissional.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Destaques:</span></strong></p>\r\n<p><span style=\"font-size: large;\">* <strong>12 esponjas macias</strong> para aplica&ccedil;&atilde;o uniforme</span></p>\r\n<p><span style=\"font-size: large;\">* <strong>F&aacute;cil de usar e lavar</strong>, prolongando a durabilidade</span></p>\r\n<p><span style=\"font-size: large;\">* <strong>Pote pr&aacute;tico e higi&ecirc;nico</strong> para armazenamento seguro</span></p>\r\n<p><span style=\"font-size: large;\">* <strong>Ideal para base</strong>, corretivo, p&oacute; e contorno</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Invista no <strong>Pote de Esponjas com 12 Unidades</strong> e tenha sempre a ferramenta certa para uma maquiagem perfeita!</span></p>', NULL, 20.00, NULL, NULL, 5.00, '', '', 0, 'S', 0.100, 'N', 0, NULL, 'S', 'pote-de-esponja-com-12-unidades', 'pote-de-esponja-com-12-unidades', 'Pote de esponja com 12 unidades', '2025-02-22 13:41:45', '2025-03-07 05:26:34', 22, 14, 6),
(3081, 'HBS02', 'UN', '0', 87, 85, 157, 'Esponja de Precisão para maquiagem Angle Blender ', 'Esponja Angle Blender Ruby Rose: aplicação precisa e acabamento perfeito. Use seca ou úmida para uma make impecável! Compre agora e arrase!', '<p><span style=\"font-size: large;\">A <strong>Esponja de Precis&atilde;o Angle Blender Ruby Rose</strong> &eacute; a ferramenta ideal para uma maquiagem impec&aacute;vel! Com seu <strong>formato angular</strong>, ela permite alcan&ccedil;ar todas as &aacute;reas do rosto com precis&atilde;o, proporcionando um acabamento uniforme e natural.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Feita com material macio e flex&iacute;vel, a esponja pode ser usada <strong>seca ou &uacute;mida</strong>, garantindo uma aplica&ccedil;&atilde;o suave e sem marcas de base, corretivo, p&oacute; e outros produtos. Seu design ergon&ocirc;mico facilita a ader&ecirc;ncia e o controle, tornando a maquiagem mais pr&aacute;tica e profissional.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong><span style=\"font-size: large;\">Destaques:</span></strong></p>\r\n<p><span style=\"font-size: large;\"><strong>* Formato angular</strong> para aplica&ccedil;&atilde;o precisa e acabamento perfeito</span></p>\r\n<p><span style=\"font-size: large;\"><strong>* Textura macia</strong> e flex&iacute;vel, ideal para uso seco ou &uacute;mido</span></p>\r\n<p><span style=\"font-size: large;\"><strong>* Distribui&ccedil;&atilde;o uniforme da maquiagem</strong> sem desperd&iacute;cio</span></p>\r\n<p><strong><span style=\"font-size: large;\">* Perfeita para base, corretivo, contorno e iluminador</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Experimente a <strong>Esponja de Precis&atilde;o Angle Blender Ruby Rose</strong> e eleve sua make a outro n&iacute;vel com praticidade e perfei&ccedil;&atilde;o!</span></p>', NULL, 11.00, NULL, NULL, 5.00, '', '', 0, 'S', 0.200, 'N', 0, NULL, 'S', 'esponja-de-precisao-para-maquiagem-angle-blender